-- Run in Supabase SQL Editor. Review roles and content before production launch.
create extension if not exists pgcrypto;
create table if not exists public.cms_editors(user_id uuid primary key references auth.users(id) on delete cascade,role text not null default 'editor' check(role in ('admin','editor')),created_at timestamptz not null default now());
create or replace function public.cms_is_editor() returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.cms_editors where user_id = (select auth.uid())) $$;
revoke all on function public.cms_is_editor() from public;
grant execute on function public.cms_is_editor() to anon, authenticated;
create or replace function public.cms_is_admin() returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.cms_editors where user_id = (select auth.uid()) and role='admin') $$;
revoke all on function public.cms_is_admin() from public;
grant execute on function public.cms_is_admin() to authenticated;
alter table public.cms_editors enable row level security;
create policy "Editors can read their own profile" on public.cms_editors for select to authenticated using (user_id = (select auth.uid()));
create policy "Admins manage editor roles" on public.cms_editors for all to authenticated using ((select public.cms_is_admin())) with check ((select public.cms_is_admin()));
-- The dashboard only accepts allowlisted fields. Database constraints and RLS are the second security boundary.
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),title text not null,slug text not null unique,summary text default '',body text default '',category text default '',location text default '',image_url text default '',gallery jsonb not null default '[]'::jsonb,completed_at date,featured boolean not null default false,status text not null default 'draft' check(status in ('draft','published','archived')),sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.posts(id uuid primary key default gen_random_uuid(),title text not null,slug text not null unique,summary text default '',body text default '',category text default '',image_url text default '',featured boolean not null default false,status text not null default 'draft' check(status in ('draft','published','archived')),published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.team_members(id uuid primary key default gen_random_uuid(),name text not null,slug text unique,role text default '',bio text default '',image_url text default '',email text default '',sort_order integer not null default 0,status text not null default 'draft' check(status in ('draft','published','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.services(id uuid primary key default gen_random_uuid(),title text not null,slug text not null unique,summary text default '',body text default '',image_url text default '',sort_order integer not null default 0,status text not null default 'draft' check(status in ('draft','published','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.testimonials(id uuid primary key default gen_random_uuid(),name text not null,role text default '',quote text not null default '',image_url text default '',sort_order integer not null default 0,status text not null default 'draft' check(status in ('draft','published','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create or replace function public.cms_set_updated_at() returns trigger language plpgsql set search_path = '' as $$ begin new.updated_at=now();return new;end $$;
do $$ declare t text;begin foreach t in array array['projects','posts','team_members','services','testimonials'] loop execute format('drop trigger if exists cms_updated_at on public.%I',t);execute format('create trigger cms_updated_at before update on public.%I for each row execute function public.cms_set_updated_at()',t);execute format('alter table public.%I enable row level security',t);execute format('create policy "Public reads published %s" on public.%I for select to anon,authenticated using (status = ''published'' or (select public.cms_is_editor()))',t,t);execute format('create policy "Editors insert %s" on public.%I for insert to authenticated with check ((select public.cms_is_editor()))',t,t);execute format('create policy "Editors update %s" on public.%I for update to authenticated using ((select public.cms_is_editor())) with check ((select public.cms_is_editor()))',t,t);execute format('create policy "Admins delete %s" on public.%I for delete to authenticated using ((select public.cms_is_admin()))',t,t);execute format('create index if not exists %I on public.%I (status,created_at desc)',t||'_public_idx',t);end loop;end $$;
-- Public read-only media bucket. Uploads require an editor role.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('monument-media','monument-media',true,8388608,array['image/jpeg','image/png','image/webp','image/avif']) on conflict(id) do update set public=true,file_size_limit=8388608,allowed_mime_types=excluded.allowed_mime_types;
create policy "CMS editors upload media" on storage.objects for insert to authenticated with check (bucket_id='monument-media' and (select public.cms_is_editor()));
create policy "CMS editors update media" on storage.objects for update to authenticated using (bucket_id='monument-media' and (select public.cms_is_editor())) with check (bucket_id='monument-media' and (select public.cms_is_editor()));
create policy "CMS admins delete media" on storage.objects for delete to authenticated using (bucket_id='monument-media' and (select public.cms_is_admin()));
